import {RULES} from './rules-config.js';
import {GROUPS} from './content.js';
import {businessType,buildingLimit} from './businesses.js';
import {businessFacts} from './business-panel.js';
import {buildingImage,guideArt} from './illustrations.js';
import {portrait} from './portraits.js';
const fmt=n=>Math.round(n).toLocaleString('zh-CN');
export function deedPortfolio(g){const p=g.s.players[0],items=g.owned(p).map(o=>({...o,value:g.cost(o.tile,o.level,businessType(o)),sale:Math.round(g.cost(o.tile,o.level,businessType(o))*RULES.propertySaleRatio)}));return {player:p,items:items.sort((a,b)=>(b.tile.id===p.pos)-(a.tile.id===p.pos)||a.tile.id-b.tile.id),value:items.reduce((sum,o)=>sum+o.value,0),sale:items.reduce((sum,o)=>sum+o.sale,0),vacant:items.filter(o=>!o.level).length};}
export function deedsPanel(g){
 const {player:p,items,value,sale,vacant}=deedPortfolio(g),c=g.char(p),mine=g.player.id===p.id&&p.human&&g.manageable(),normal=mine&&g.s.phase!=='debt',view=!p.alive?'你已退出本局，查看最终地产。':g.player.id!==p.id?'电脑回合，当前仅查看你的地产。':!g.manageable()?'移动结束后可继续经营。':'普通建设需停到对应地块，每次停靠建设一次。';
 return `<div class="deeds-owner"><span>${portrait(c.id)}</span><div><strong>${c.name}的地产簿</strong><small>${view}</small></div></div><div class="deeds-totals"><div><span>我的地块</span><b>${items.length}<small> 块 · ${vacant} 块待建</small></b></div><div><span>地产估值</span><b>${fmt(value)}</b></div><div><span>全部变卖可得</span><b>${fmt(sale)}</b></div></div><p class="deeds-explain">估值按购地与建设成本计入净资产；变卖按每块地产成本的 65% 四舍五入。</p>${items.length?items.map(o=>{const id=o.tile.id,build=normal&&(g.canUpgrade(id)||g.canBuild(id)),local=p.buildSite===id&&p.pos===id&&g.s.phase==='end';return `<article class="row estate-row deed-card" data-deed="${id}" style="--estate-color:${c.estateColor}">${buildingImage({...o.tile,buildingType:o.buildingType},o.level,c.estateColor)}<div class="row-head"><strong><i style="background:${GROUPS[o.tile.group].color}"></i>${o.tile.name}</strong><span class="badge">${o.level?o.level+' 级':'待建空地'}</span></div>${businessFacts(g,id)}<div class="deed-values"><span>估值 <b>${fmt(o.value)}</b></span><span>变卖 <b>+${fmt(o.sale)}</b></span></div><div class="row-actions"><button class="secondary" data-act="locateDeed" data-id="${id}">定位与详情 ↗</button><button class="${build?'primary':'secondary'}" data-act="${o.level?'upgrade':'chooseBuilding'}" data-id="${id}" ${build?'':'disabled'}>${o.level>=buildingLimit(o)?'已达上限':!mine?'本回合不可建设':!local?'停到这里再建设':!o.level?'选择建筑':`加盖 · ${fmt(g.buildPrice(o.tile))}`}</button><button class="secondary" data-act="confirmDemolish" data-id="${id}" ${normal&&local&&o.level?'':'disabled'}>拆除房屋</button><button class="secondary" data-act="confirmSell" data-id="${id}" ${mine?'':'disabled'}>变卖 +${fmt(o.sale)}</button></div></article>`;}).join(''):`${guideArt('house','走到无主地产后可以买下第一块地；空地到访后可选择七类建筑。','naishu')}<div class="empty">还没有自己的地块，下一站去看看吧。</div>`}`;
}
